import type { Q } from "../types";

export const civil2: Q[] = [
  // ---- Geotechnical ----
  { t: "Effective stress principle", p: "State the effective stress principle and explain why it governs soil strength and settlement.", d: 2, tp: "geotechnical", i: "Effective stress σ' = σ − u, total stress minus pore water pressure. Soil strength and volume change depend on the stress carried by the soil skeleton, not on the water. Raising the water table lowers effective stress and strength, and loading saturated clay first raises pore pressure, which then dissipates (consolidation) as effective stress and settlement increase. Liquefaction occurs when pore pressure rises to equal total stress.", c: ["σ' = σ − u", "Strength depends on effective stress", "Rising water table reduces effective stress", "Consolidation and liquefaction follow from pore pressure change"], k: ["Water pressure carries no frictional resistance", "Drained and undrained conditions give different strengths"], m: ["Using total stress for drained strength"] },
  { t: "Bearing capacity failure modes", p: "Describe general shear, local shear and punching failure of a shallow foundation and which soils suit each.", d: 2, tp: "geotechnical", i: "General shear failure occurs in dense or stiff soil with a clearly defined failure surface and heave at the surface, with a peak load. Local shear occurs in medium dense soils, with partial failure surfaces. Punching shear in loose or soft soil shows steady settlement without a clear peak. Terzaghi's bearing capacity equation combines cohesion, overburden and width terms with factors depending on friction angle.", c: ["General shear in dense or stiff soil with a peak load", "Local shear in medium soil", "Punching in loose or soft soil", "Terzaghi equation combines cohesion, overburden and width terms"], k: ["Footing width, depth and groundwater all change capacity", "Settlement may govern before capacity does"], m: ["Assuming one failure mode for all soils"] },
  { t: "Consolidation time and drainage path", p: "Why does doubling the thickness of a clay layer increase consolidation time about fourfold?", d: 3, tp: "geotechnical", i: "The time factor T_v = c_v·t/H_dr² for a given degree of consolidation, where H_dr is the longest drainage path. For a fixed T_v, time scales with the square of drainage path, so doubling the drainage path (for the same drainage boundaries) multiplies time by four. Double drainage, with permeable layers above and below, halves the path. Vertical drains shorten the path to speed consolidation.", c: ["T_v = c_v t / H_dr²", "Time scales with the square of the drainage path", "Double drainage halves the path", "Vertical drains accelerate consolidation"], k: ["c_v is determined from oedometer tests", "Clays can take years to consolidate"], m: ["Thinking time scales linearly with thickness"] },
  { t: "Slope stability: factor of safety and what changes it", p: "What controls the stability of a soil slope, and what triggers failures after heavy rain?", d: 2, tp: "geotechnical", i: "Factor of safety is shear strength divided by the shear stress needed for equilibrium along a potential slip surface. Steeper or taller slopes, added loads at the crest, loss of toe support, lower strength and higher pore water pressure reduce it. Heavy rain raises pore pressures and soil weight and may remove suction in unsaturated soil, so failures often follow storms. Remedies include flattening, drainage, retaining structures and reinforcement.", c: ["FS = available strength over required strength", "Geometry, loads and strength control stability", "Rainfall raises pore pressure and reduces suction", "Drainage, flattening and retaining measures help"], k: ["Methods include Bishop and Janbu limit equilibrium", "Long-term strength can be lower than short-term"], m: ["Ignoring pore pressure"] },
  { t: "Lateral earth pressure: active, passive and at rest", p: "Explain the three lateral earth pressure states and which requires the most wall movement.", d: 2, tp: "geotechnical", i: "At-rest pressure applies to non-yielding walls, with coefficient K₀ ≈ 1 − sinφ. Active pressure develops when the wall moves slightly away from the soil, mobilising full shear strength and giving the minimum lateral pressure, with K_a = tan²(45° − φ/2). Passive pressure develops when the wall pushes into the soil, giving the maximum pressure with K_p = tan²(45° + φ/2), and needs the largest movement to mobilise.", c: ["At-rest K0 for non-yielding walls", "Active is minimum with small outward movement", "Passive is maximum and needs large movement", "Coefficients depend on friction angle"], k: ["Passive resistance is often reduced by a factor for safety", "Surcharges and water add pressure"], m: ["Using passive pressure without allowing for the required movement"] },
  { t: "Liquefaction mechanism and mitigation", p: "What is soil liquefaction, which soils are susceptible, and how can it be reduced?", d: 3, tp: "geotechnical", i: "Cyclic shaking of loose saturated sand tends to compact the soil, but with no time to drain, pore pressure builds until it equals the overburden stress, effective stress drops to zero and the soil behaves like a liquid, causing settlement, lateral spreading and loss of bearing. Loose clean sands and silty sands are most susceptible. Mitigation densifies the soil (vibro-compaction, stone columns), improves drainage, grouts or replaces material, or uses deep foundations to firm layers.", c: ["Pore pressure builds under cyclic loading and effective stress falls to zero", "Loose saturated sands are most susceptible", "Consequences: settlement, spreading and loss of bearing", "Densification, drainage or deep foundations mitigate"], k: ["Earthquake magnitude and duration matter", "Screening uses SPT or CPT data"], m: ["Thinking only loose sand above water table liquefies"] },
  { t: "Soil investigation planning", p: "How would you plan a site investigation for a mid-rise building?", d: 1, tp: "geotechnical", i: "Start with a desk study of geology, maps and existing records, then borings or cone penetration tests to a depth beyond the stress influence of the foundations (typically 1.5 to 2 times the footing width, or to bedrock or competent soil), with spacing that reflects variability. Sample for laboratory classification, strength and consolidation tests, record groundwater and run in-situ tests. The report gives parameters and recommendations.", c: ["Desk study first", "Borings or CPT to sufficient depth and spacing", "Sampling and laboratory testing", "Groundwater observation and a report with recommendations"], k: ["Investigation cost is small versus the risk of surprise", "Spacing depends on soil variability"], m: ["Drilling too shallow to capture compressible layers"] },
  { t: "Pile capacity: end bearing and skin friction", p: "How do you estimate axial capacity of a driven pile, and how is it verified?", d: 2, tp: "geotechnical", tp2: "structural-design", i: "Ultimate capacity is the sum of shaft resistance (unit skin friction times surface area along the pile) and end bearing (unit base resistance times tip area), estimated using soil parameters from borings or CPT data with static formulas. It is verified by static or dynamic load tests, or pile driving analysis with signal matching, and design capacity applies a resistance factor or factor of safety. Group effects can reduce group capacity or increase settlement.", c: ["Capacity = shaft friction + end bearing", "Estimated from soil investigation data", "Verified by load tests or dynamic analysis", "Group effects and factors of safety"], k: ["Skin friction mobilises at small displacement; end bearing needs more", "Negative skin friction adds load in settling soils"], m: ["Neglecting group effects"] },
  { t: "Compaction and proctor tests", p: "What does a Proctor test tell you, and how is field compaction controlled?", d: 1, tp: "geotechnical", tp2: "civil-materials", i: "The Proctor test determines how dry density varies with moisture content under a standard compaction effort, giving the maximum dry density and optimum moisture content. At low moisture, friction resists compaction, and at high moisture, water fills voids and cannot be expelled. In the field, specified relative compaction (such as 95 percent of maximum) is checked by density tests, with moisture controlled at placement.", c: ["Dry density versus moisture curve", "Maximum dry density at optimum moisture", "Too dry or too wet reduces density", "Field density tests check relative compaction"], k: ["Higher compaction effort raises density and lowers optimum moisture", "Lift thickness affects achievable density"], m: ["Compacting soil far wetter than optimum"] },
  { t: "Expansive soils and foundation effects", p: "Why do expansive clays damage lightly loaded structures, and what design responses exist?", d: 2, tp: "geotechnical", i: "Clays with swelling minerals expand when wetted and shrink when dried, with seasonal and localised moisture changes causing differential heave that cracks floors and walls, especially under lightly loaded slabs. Responses include moisture control and drainage, replacing or treating the soil (lime), stiffened or post-tensioned slabs, deep foundations with voids to isolate the soil and allowing movement in the structure.", c: ["Swelling minerals expand when wetted", "Differential movement cracks structures", "Control moisture and drainage", "Stiffened slabs, deep foundations or soil treatment"], k: ["Vegetation affects local moisture", "Heavily loaded footings resist swelling better"], m: ["Designing slabs on expansive clay without movement provisions"] },
  { t: "Dewatering during excavation", p: "Why can excavating below the water table cause instability, and how do you control it?", d: 2, tp: "geotechnical", tp2: "construction-management", i: "Groundwater seeping into an excavation reduces effective stress and creates upward seepage that can cause piping, boiling or base heave in sands, and increases lateral loads on supports. Control by lowering the water table with wellpoints, deep wells or sumps, or by cut-off walls such as sheet piles or slurry walls, and monitor drawdown effects on adjacent structures from consolidation settlement.", c: ["Seepage reduces effective stress and causes boiling or heave", "Wellpoints, deep wells and sumps lower the water table", "Cut-off walls block flow", "Drawdown can settle neighbouring structures"], k: ["Exit gradient indicates piping risk", "Monitoring wells verify performance"], m: ["Ignoring the impact on adjacent buildings"] },
  { t: "Shear strength tests: direct shear versus triaxial", p: "What advantages does a triaxial test have over a direct shear test?", d: 2, tp: "geotechnical", i: "Triaxial tests allow control of drainage, measurement of pore pressure, and a well-defined stress state with a free failure plane, and can model drained or undrained conditions with confining pressure reflecting the field. Direct shear is simple and quick and forces failure on a predetermined plane with poorly controlled drainage and non-uniform stresses. Triaxial results are preferred for design parameters of clays and effective stress analyses.", c: ["Triaxial controls drainage and measures pore pressure", "Failure plane is free to develop", "Direct shear is simple but forces the failure plane", "Triaxial preferred for effective stress parameters"], k: ["Undrained and drained tests give different parameters", "Sample disturbance affects results"], m: ["Using drained parameters for rapid loading of clay"] },
  { t: "Settlement: immediate, consolidation and secondary", p: "Describe the three components of foundation settlement.", d: 2, tp: "geotechnical", i: "Immediate (elastic) settlement happens as loads are applied, without volume change in saturated clays and with volume change in sands. Primary consolidation occurs as excess pore pressure dissipates from clays and water is squeezed out, taking months to years. Secondary compression is creep of the soil skeleton at constant effective stress, continuing long after, significant in organic and soft clays. The total is the sum, and differential settlement causes distress.", c: ["Immediate elastic settlement", "Primary consolidation from pore pressure dissipation", "Secondary compression as creep", "Differential settlement causes damage"], k: ["Sands settle quickly; clays settle slowly", "Preloading removes much of the primary settlement"], m: ["Reporting only immediate settlement"] },
  // ---- Hydraulics & hydrology ----
  { t: "Hydrograph and time of concentration", p: "What is a hydrograph, and how does urbanisation change its shape?", d: 2, tp: "hydraulics-hydrology", i: "A hydrograph plots discharge against time at a point in a stream following rainfall. Urbanisation increases impervious area and speeds drainage through pipes and smooth channels, which shortens the time of concentration, raises peak discharge and increases total runoff volume, giving a taller, earlier peak. Detention basins, green infrastructure and infiltration flatten and delay the peak.", c: ["Hydrograph plots flow against time", "Urbanisation increases impervious area", "Higher, earlier and larger peak", "Detention and infiltration flatten the peak"], k: ["Time of concentration is the travel time from the farthest point", "Unit hydrograph theory predicts response"], m: ["Thinking only volume changes, not timing"] },
  { t: "Design storm and return period", p: "What does a 100-year storm mean, and how is a design return period chosen?", d: 1, tp: "hydraulics-hydrology", i: "A 100-year event has a one percent chance of being equalled or exceeded in any given year, not once exactly every hundred years. The probability of at least one such event in a 30-year period is about 26 percent. Return period is chosen from consequences of failure and cost: drainage of minor streets may use 2 to 10 years, culverts 25 to 50 years and critical structures such as dams far higher.", c: ["One percent annual exceedance probability", "Not a once-per-century schedule", "Probability over a design life is much larger", "Selection based on consequence and cost"], k: ["Climate change shifts rainfall statistics", "Risk accumulates across years"], m: ["Believing a 100-year event cannot happen twice in a century"] },
  { t: "Culvert design: inlet versus outlet control", p: "How do inlet control and outlet control differ for a culvert, and which governs when?", d: 3, tp: "hydraulics-hydrology", i: "In inlet control the flow capacity is limited by the entrance geometry, headwater depth and barrel area, with the barrel flowing partly full, typical for steep culverts. In outlet control the capacity is limited by barrel friction, length, slope and tailwater, so the barrel flows full; typical for flat, long culverts or high tailwater. Designers compute headwater for both conditions and the larger value governs.", c: ["Inlet control limited by entrance and headwater", "Outlet control limited by friction, length and tailwater", "Steep short culverts are usually inlet controlled", "Compute both and use the higher headwater"], k: ["Entrance shape changes inlet capacity significantly", "Debris can block the inlet"], m: ["Checking only one control condition"] },
  { t: "Open channel flow: critical depth and Froude number", p: "What is critical depth, and how do subcritical and supercritical flows differ in behaviour?", d: 2, tp: "hydraulics-hydrology", tp2: "fluid-mechanics", i: "Critical depth is the depth at which specific energy is a minimum for a given discharge, where the Froude number Fr = V/√(gy) equals one. Subcritical flow (Fr < 1) is deep and slow, with disturbances travelling upstream, so downstream conditions control it. Supercritical flow (Fr > 1) is shallow and fast, controlled from upstream, and a hydraulic jump forms when it returns to subcritical flow, dissipating energy.", c: ["Critical depth at minimum specific energy", "Froude number equals one", "Subcritical flow is controlled from downstream", "Supercritical flow is controlled from upstream and ends in a hydraulic jump"], k: ["Hydraulic jumps are used for energy dissipation", "Channel transitions can induce critical flow"], m: ["Mixing up the control directions"] },
  { t: "Stormwater detention basin sizing concept", p: "How do you estimate the storage a detention basin needs to limit post-development peak to pre-development flow?", d: 2, tp: "hydraulics-hydrology", i: "Compute the pre-development peak allowed and the post-development inflow hydrograph, then route the inflow through the basin with an outlet structure whose discharge limits the outflow to the allowed peak. The storage required is the maximum difference between cumulative inflow and outflow volume. Iterate outlet size and storage until the target peak is met, checking multiple storm durations and emergency spillway capacity.", c: ["Set the allowed peak from pre-development conditions", "Route the inflow hydrograph through the outlet", "Storage equals the maximum cumulative inflow minus outflow", "Check multiple durations and an emergency spillway"], k: ["Critical duration may be longer than the time of concentration", "Release control prevents downstream flooding"], m: ["Sizing for only one storm duration"] },
  { t: "Bridge scour", p: "What is scour at a bridge pier and how is it addressed?", d: 2, tp: "hydraulics-hydrology", tp2: "structural-design", i: "Flow accelerating around piers and abutments removes streambed material, forming scour holes that undermine foundations, a leading cause of bridge failure during floods. Estimate scour depth from flow, pier shape, sediment and flood magnitude using standard methods, and design foundations below it. Protection uses riprap, collars, deeper foundations and monitoring after floods.", c: ["Accelerated flow erodes the bed around piers", "Undermining causes failures in floods", "Foundations placed below the calculated scour depth", "Riprap and monitoring protect bridges"], k: ["Local, contraction and general scour add up", "Debris accumulation worsens scour"], m: ["Designing foundations at the existing streambed level"] },
  { t: "Pipe network analysis: Hardy Cross concept", p: "How does the Hardy Cross method balance flows in a looped water distribution network?", d: 3, tp: "hydraulics-hydrology", tp2: "fluid-transport", i: "Assume initial flows satisfying continuity at nodes, then in each loop compute head loss around the loop with signs by direction, which should sum to zero. Correct the flows in the loop by ΔQ = −Σh_f / (Σ n·|h_f/Q|) and iterate until corrections are small. Modern software solves the same equations simultaneously using Newton methods, but the concept shows continuity and energy balance.", c: ["Initial flows satisfy continuity", "Loop head losses should sum to zero", "Apply a flow correction ΔQ per loop", "Iterate until converged"], k: ["Continuity at nodes and energy around loops are the governing equations", "Software handles pumps, tanks and valves too"], m: ["Ignoring flow direction signs in head loss sums"] },
  { t: "Water hammer in distribution pipelines", p: "What design measures protect water mains from pressure surges?", d: 2, tp: "hydraulics-hydrology", tp2: "fluid-mechanics", i: "Slow-closing valves, controlled pump start and stop with soft starters or variable frequency drives, surge tanks or air vessels that absorb pressure waves, pressure relief or air valves to prevent column separation and anticipator valves limit surge. Pipe class and restraint of bends must handle residual surges, and surge analysis identifies worst cases such as pump trip.", c: ["Slow valves and pump control", "Surge tanks and air vessels", "Relief and air valves", "Surge analysis for worst cases such as a pump trip"], k: ["Pipe material stiffness changes wave speed", "Column separation causes severe pressure spikes"], m: ["Designing pipe pressure class for static pressure only"] },
  { t: "Infiltration and runoff: SCS curve number", p: "How does the curve number method estimate runoff, and what affects the curve number?", d: 2, tp: "hydraulics-hydrology", i: "The SCS-CN method computes runoff from rainfall using Q = (P − 0.2S)²/(P + 0.8S), with S = 25400/CN − 254 in millimetres. The curve number depends on soil hydrologic group (infiltration capacity), land cover and treatment, and antecedent moisture. Paved surfaces have curve numbers near 98, and forests on well-drained soils may be 30 to 55, so land-use change strongly changes runoff.", c: ["Runoff from rainfall and retention S", "Curve number depends on soil group and land cover", "Antecedent moisture matters", "Urbanisation raises curve numbers"], k: ["Runoff only begins after initial abstraction", "Method suits small to medium catchments"], m: ["Using it without adjusting for wet antecedent conditions"] },
  { t: "Floodplain management and flood frequency analysis", p: "How do engineers estimate flood flows at sites with long records and at ungauged sites?", d: 3, tp: "hydraulics-hydrology", i: "With long gauge records, annual maximum series are fitted to distributions such as Log-Pearson III or Gumbel to estimate flows at chosen return periods with confidence intervals. At ungauged sites, methods use regional regression on catchment characteristics, rainfall-runoff models with design storms and transfer from similar gauged catchments. Floodplain mapping then uses hydraulic models to define flood extent and levels.", c: ["Fit annual maxima to extreme value distributions", "Confidence intervals reflect record length", "Regional regression or rainfall-runoff models for ungauged sites", "Hydraulic modelling maps flood extents"], k: ["Extrapolating far beyond record length is uncertain", "Stationarity assumptions are questioned under climate change"], m: ["Treating fitted values as exact"] },
  // ---- Transportation ----
  { t: "Highway capacity and level of service", p: "What do capacity and level of service mean for a highway, and which factors reduce capacity?", d: 2, tp: "transportation", i: "Capacity is the maximum hourly flow that can be sustained, around 2,200 passenger cars per hour per lane for ideal freeway conditions. Level of service grades operating quality from A (free flow) to F (breakdown) based on density or delay. Capacity falls with narrow lanes, restricted shoulders, heavy vehicles, grades, weaving and incidents, and flow breakdown makes throughput drop below capacity.", c: ["Capacity is the maximum sustainable flow", "Level of service grades quality A through F", "Heavy vehicles, grades and narrow lanes reduce capacity", "Breakdown lowers throughput"], k: ["Density is the key measure on freeways", "Peak-hour factor accounts for short-term surges"], m: ["Assuming more speed means more flow at all densities"] },
  { t: "Traffic signal timing basics", p: "Explain cycle length, green split and why too short or too long a cycle hurts performance.", d: 2, tp: "transportation", i: "The cycle is the total time to serve all phases, and green splits allocate the cycle among phases in proportion to demand. Too short a cycle wastes a large share on lost time (clearance and start-up), cutting capacity, while too long a cycle increases delay for waiting drivers and queue spillback. Webster's formula gives an optimal cycle from lost time and flow ratios, and coordination aligns offsets along a corridor.", c: ["Cycle is the total time to serve all phases", "Green splits follow demand", "Short cycles waste lost time; long cycles increase delay", "Offsets coordinate adjacent signals"], k: ["Pedestrian crossing time sets minimum greens", "Adaptive systems adjust to demand"], m: ["Assuming a longer cycle always increases capacity without cost"] },
  { t: "Pavement design: flexible versus rigid", p: "Compare flexible asphalt and rigid concrete pavements in load distribution, cost and maintenance.", d: 2, tp: "transportation", tp2: "civil-materials", i: "Flexible pavements distribute loads through layered granular materials, with stress spreading and decreasing with depth, so subgrade strength and layer thickness matter, and they can be repaired and overlaid easily but suffer rutting and fatigue cracking. Rigid pavements spread loads through slab bending stiffness over a large area, last longer with less maintenance but cost more initially and need joints and sound base support. Choice depends on traffic, climate, subgrade and life-cycle cost.", c: ["Flexible pavements spread loads through layers", "Rigid pavements carry loads by slab stiffness", "Flexible: lower initial cost, more maintenance", "Rigid: higher initial cost, long life, joints"], k: ["Subgrade strength drives thickness", "Life-cycle cost comparison guides selection"], m: ["Comparing on initial cost only"] },
  { t: "Geometric design: sight distance and curve radius", p: "How do stopping sight distance and design speed influence horizontal and vertical curve design?", d: 2, tp: "transportation", i: "Stopping sight distance is reaction distance plus braking distance, and rises with the square of speed, so higher speeds need longer sight lines. Vertical crest curves must be long enough for drivers to see an obstacle in time, and horizontal curves need adequate radius and superelevation for lateral acceleration using e + f = v²/(gR), with obstructions on the inside cleared. Design speed links these elements consistently.", c: ["Stopping distance is reaction plus braking distance", "Grows with speed squared", "Crest curve length ensures visibility", "Horizontal curve uses superelevation and side friction"], k: ["Friction limits are lower in wet conditions", "Consistency avoids sudden speed changes"], m: ["Ignoring reaction time"] },
  { t: "Roundabouts versus signalised intersections", p: "What are the safety and capacity advantages of modern roundabouts over signals?", d: 2, tp: "transportation", i: "Roundabouts reduce conflict points and enforce low speed with deflection, converting right-angle and head-on crashes into low-speed merging, cutting fatal and injury crashes substantially. They have lower delay at moderate volumes, as there is no stop for free-flowing movements, and no signal equipment to maintain. At very high volumes or heavy pedestrian activity, capacity limits and pedestrian accommodation need careful design.", c: ["Fewer conflict points and low speed", "Reduced severe crashes", "Lower delay at moderate volumes", "Limits at very high volumes and for pedestrian provision"], k: ["Entry deflection controls speed", "Multi-lane designs raise complexity"], m: ["Assuming they work well at all volumes"] },
  { t: "Traffic flow fundamental diagram", p: "Describe the relationship between traffic flow, density and speed, and what it implies for congestion.", d: 3, tp: "transportation", i: "Flow equals density times speed. At low density vehicles travel at free-flow speed and flow rises with density, but beyond a critical density speed drops fast enough that flow peaks (capacity) and then falls, in the congested branch, until jam density where flow is zero. Shock waves propagate upstream when density changes, explaining stop-and-go waves, and ramp metering or speed harmonisation keep density below critical.", c: ["Flow = density × speed", "Flow peaks at capacity at critical density", "Congested branch has falling flow", "Shock waves and ramp metering"], k: ["Throughput falls in congestion, a capacity drop", "Speed harmonisation reduces breakdown"], m: ["Assuming adding vehicles always adds flow"] },
  { t: "Pedestrian and cyclist safety design", p: "What infrastructure design features most effectively reduce vulnerable-road-user fatalities?", d: 1, tp: "transportation", i: "Lower vehicle speeds are the most powerful factor, since fatality risk rises steeply with impact speed, so traffic calming, narrower lanes and speed limits matter. Physical separation of cyclists and pedestrians from fast traffic, raised crossings, refuge islands, good lighting, shorter crossing distances and protected intersection designs reduce exposure and conflict severity.", c: ["Lower vehicle speed", "Physical separation from fast traffic", "Raised crossings, refuges and lighting", "Shorter crossing distances and protected intersections"], k: ["Impact speed strongly governs survival", "Visibility and driver expectation matter"], m: ["Relying on signs alone"] },
  { t: "Transportation demand forecasting: four-step model", p: "Outline the four steps of the classic transportation demand model.", d: 2, tp: "transportation", i: "Trip generation estimates trips produced and attracted by zones from land use and demographics. Trip distribution matches origins and destinations, often with a gravity model. Mode choice splits trips among car, transit, walking and cycling using utility or logit models. Route assignment loads trips onto the network, typically with equilibrium so that no traveller can save time by changing route, producing flows for evaluating projects.", c: ["Trip generation", "Trip distribution using a gravity model", "Mode choice using logit models", "Route assignment with equilibrium"], k: ["Feedback between congestion and demand matters", "Induced demand is a known limitation"], m: ["Assuming demand is fixed regardless of capacity"] },
  { t: "Pavement distresses and maintenance strategy", p: "Name common pavement distresses and the timing logic of preventive versus corrective maintenance.", d: 1, tp: "transportation", tp2: "civil-materials", i: "Common distresses are rutting, fatigue (alligator) cracking, thermal cracking, potholes, raveling and joint faulting. Pavement condition decays slowly at first and then quickly, so preventive treatments such as crack sealing and thin overlays applied early are far cheaper per year of life than rehabilitation after deterioration. Pavement management systems schedule treatments to maximise network condition within budget.", c: ["Rutting, fatigue cracking and potholes", "Deterioration accelerates after initial slow decay", "Preventive treatment early is cheaper", "Management systems optimise the budget"], k: ["Water is a main cause of deterioration", "Drainage maintenance extends life"], m: ["Waiting until failure to repair"] },
  { t: "Railway track basics: ballast, ties and rail", p: "What roles do rail, ties and ballast play in track structure?", d: 1, tp: "transportation", i: "Rails guide wheels and carry bending loads between supports. Ties (sleepers) hold the gauge and distribute wheel loads to the ballast. Ballast, crushed stone, spreads load over the subgrade, provides drainage and resilience and allows track geometry adjustment by tamping. Continuous welded rail removes joints but needs management of thermal forces to prevent buckling in heat and pull-apart in cold.", c: ["Rails guide and carry loads", "Ties hold gauge and spread load", "Ballast distributes loads and drains", "Continuous welded rail needs thermal force management"], k: ["Track geometry degrades with traffic and needs tamping", "Subgrade quality limits track life"], m: ["Ignoring thermal buckling"] },
  // ---- Construction management ----
  { t: "Critical path method basics", p: "Explain the critical path, float, and how a delay in a non-critical task affects the project.", d: 1, tp: "construction-management", tp2: "project-management", i: "The critical path is the longest chain of dependent activities, determining the minimum project duration, and any delay on it delays the project. Float (slack) is the time an activity can slip without delaying the project, and total float is zero on the critical path. A delay in a non-critical task consumes float; once float is exhausted the task becomes critical. Forward and backward passes compute early and late dates.", c: ["Critical path is the longest chain", "Delay on it delays the project", "Float is available slack", "Forward and backward passes compute dates"], k: ["Resource limits can change the critical path", "Multiple near-critical paths increase risk"], m: ["Assuming all tasks affect completion equally"] },
  { t: "Construction cost estimating levels", p: "How do estimates differ at concept, design development and bid stages, and what is contingency for?", d: 2, tp: "construction-management", i: "Early concept estimates use cost per unit area or historical data with wide accuracy ranges (±30 percent or more). Design development estimates use quantity take-offs with unit costs, narrowing to ±15 percent, and bid estimates use detailed quantities, subcontractor quotes, labour and equipment productivity, overhead and profit. Contingency covers uncertainty in scope, price and risk, and should shrink as design matures, with escalation separate.", c: ["Concept estimates are rough with wide ranges", "Quantity take-offs tighten accuracy", "Bid estimates use detailed quantities and quotes", "Contingency covers uncertainty and decreases with design maturity"], k: ["Allowances for known unknowns differ from contingency", "Market conditions shift unit prices"], m: ["Treating early estimates as firm prices"] },
  { t: "Construction site safety hierarchy of controls", p: "Describe the hierarchy of controls and apply it to a fall-from-height hazard.", d: 1, tp: "construction-management", tp2: "ergonomics", i: "From most to least effective: eliminate the hazard, substitute, use engineering controls, administrative controls and personal protective equipment. For work at height, first avoid it by prefabricating on the ground, then use guardrails, scaffolds or safety nets as engineering controls, then procedures, training and permits, and finally harnesses as the last line of defence, with rescue plans.", c: ["Elimination, substitution, engineering, administrative, PPE", "Avoid work at height by prefabrication", "Guardrails and nets before harnesses", "Procedures, training and rescue planning"], k: ["PPE relies on human behaviour", "Collective protection protects everyone"], m: ["Relying on harnesses as the first measure"] },
  { t: "Earned value management", p: "Interpret CPI and SPI and what each tells you about a project in progress.", d: 2, tp: "construction-management", tp2: "project-management", i: "Earned value compares planned value (PV), earned value (EV) and actual cost (AC). Schedule performance index SPI = EV/PV: below 1 means behind schedule. Cost performance index CPI = EV/AC: below 1 means over budget. A project with CPI 0.9 forecasts final cost near budget over 0.9, using estimate at completion. Trends indicate whether recovery is realistic.", c: ["PV, EV and AC definitions", "SPI = EV/PV", "CPI = EV/AC", "Forecast estimate at completion from the trend"], k: ["EV measures work completed in budget terms", "Early cost trends tend to persist"], m: ["Reading SPI as a measure of cost"] },
  { t: "Contract types and risk allocation", p: "Compare lump-sum, cost-plus and unit-price contracts and who bears which risk.", d: 2, tp: "construction-management", i: "Lump-sum fixes price for defined scope, placing cost risk on the contractor but needing complete design and giving change orders when scope changes. Cost-plus reimburses actual cost plus fee, placing cost risk on the owner but allowing early start and flexibility, so cost caps or guaranteed maximum prices are common. Unit-price contracts pay per measured quantity, sharing quantity risk with the owner, suited to earthwork and uncertain quantities.", c: ["Lump sum: contractor carries cost risk with defined scope", "Cost-plus: owner carries cost risk", "Unit price: owner carries quantity risk", "Guaranteed maximum price blends features"], k: ["Design completeness decides suitability", "Incentives shape behaviour"], m: ["Assuming one contract type suits all projects"] },
  { t: "Quality control in concrete placement", p: "What tests and inspections ensure quality for concrete placed on a construction site?", d: 1, tp: "construction-management", tp2: "civil-materials", i: "Check batch tickets and mix design, then test fresh concrete for slump, air content and temperature on delivery, and cast cylinders or cubes for compressive strength at 7 and 28 days. Inspect reinforcement placement, cover and formwork before the pour, control consolidation and curing, and document results. Non-conforming results trigger investigation, cores or load tests.", c: ["Check the batch ticket and mix design", "Slump, air content and temperature tests", "Cylinders for strength at 7 and 28 days", "Inspect reinforcement, cover, consolidation and curing"], k: ["Field-cured samples reflect in-place strength", "Records support acceptance"], m: ["Adding water on site to increase slump"] },
  { t: "Lean construction and last planner system", p: "How does the Last Planner System reduce delays on construction projects?", d: 2, tp: "construction-management", tp2: "lean-manufacturing", i: "It plans in layers: master schedule, phase pull planning with all trades, look-ahead planning that removes constraints before work is due, and weekly work plans made by those who do the work. Percent plan complete tracks reliability, and root causes of missed commitments drive improvement. Making only ready work commitments reduces waiting, rework and variability.", c: ["Layered planning from master to weekly plans", "Pull planning with trades", "Look-ahead removes constraints early", "Percent plan complete measures reliability"], k: ["Commitments come from the people doing the work", "Constraint removal prevents rework"], m: ["Planning only at the master schedule level"] },
  { t: "Excavation shoring and trench safety", p: "Why are trench collapses so deadly, and what protective systems are used?", d: 1, tp: "construction-management", tp2: "geotechnical", i: "A cubic metre of soil weighs about 1.6 tonnes, so even small cave-ins bury and crush workers, and sidewalls can fail without warning, especially after rain or vibration. Protection is sloping or benching the walls to safe angles for the soil type, shoring with hydraulic or timber supports, or trench boxes, plus keeping spoil back from edges, providing ladders and inspection by a competent person daily.", c: ["Soil mass is large and collapses suddenly", "Sloping, benching, shoring or trench boxes", "Keep spoil away from the edge", "Daily competent-person inspection and access ladders"], k: ["Soil type determines safe slope", "Water and vibration reduce stability"], m: ["Entering a trench with no protection because it is shallow"] },
  { t: "Value engineering versus cost cutting", p: "How does value engineering differ from simply cutting cost?", d: 1, tp: "construction-management", i: "Value engineering is a structured review of function: define what each element must do, then find alternatives that provide the required performance at lower life-cycle cost, without reducing quality, safety or function. Simple cost cutting removes scope or quality, often shifting costs to maintenance or risk. Done early with the design team, VE yields savings; late VE tends to cause redesign cost.", c: ["Focus on function and life-cycle cost", "Maintains required performance", "Cost cutting removes scope or quality", "Early VE is more effective than late VE"], k: ["Life-cycle thinking avoids false savings", "Stakeholder agreement defines required function"], m: ["Equating cheaper with better value"] },
  { t: "Building information modelling uses on projects", p: "What practical benefits does BIM offer during design and construction?", d: 1, tp: "construction-management", i: "A coordinated 3D model carrying data lets teams detect clashes between structure and services before construction, extract quantities for estimates, simulate construction sequences, and share a single source of information among disciplines. It supports prefabrication, facility management handover and reduces rework. Benefits depend on agreed standards for model content and discipline in keeping the model current.", c: ["Coordinated 3D data model", "Clash detection before construction", "Quantity extraction and sequencing", "Facility handover and prefabrication support"], k: ["Model quality depends on information standards", "Rework avoidance gives the largest savings"], m: ["Treating BIM as just 3D drawings"] },
  { t: "Risk register and contingency planning on a project", p: "How do you build and use a risk register on a construction project?", d: 2, tp: "construction-management", tp2: "project-management", i: "List risks with description, cause, probability and impact, score and rank them, assign owners and responses (avoid, mitigate, transfer, accept) and track triggers. Quantify high risks for cost and schedule contingency, using ranges or Monte Carlo simulation. Review regularly, retire closed risks and add new ones, so the register guides decisions instead of being a one-time document.", c: ["Probability, impact and ranking", "Owners and responses: avoid, mitigate, transfer, accept", "Quantify to size contingency", "Review regularly"], k: ["Risk owners are accountable for actions", "Unrealistic optimism is a common bias"], m: ["Creating the register once and not updating it"] },
  // ---- extras ----
  { t: "Wind loads on buildings and cladding", p: "How are wind loads determined for a building's structure versus its cladding, and why are local pressures higher?", d: 2, tp: "structural-design", tp2: "structural-analysis", i: "Design wind speed from the site's reference speed, exposure and topography gives velocity pressure, multiplied by pressure coefficients for shape and gust effects. The main structure sees averaged pressures over large areas, but cladding and fixings sense short-duration local suction peaks at edges, corners and roofs, so component and cladding pressures are higher. Tall flexible buildings also need dynamic checks for vortex shedding and acceleration comfort.", c: ["Velocity pressure from speed, exposure and topography", "Pressure coefficients for shape and gusts", "Local suction peaks at edges and corners", "Dynamic checks for tall buildings"], k: ["Small tributary areas have higher peak coefficients", "Wind tunnel testing refines complex shapes"], m: ["Using the main-frame pressure for cladding fixings"] },
  { t: "Steel beam lateral-torsional buckling", p: "What is lateral-torsional buckling and how do you prevent it in a steel beam?", d: 3, tp: "structural-design", tp2: "structural-analysis", i: "An unbraced I-beam loaded in strong-axis bending can suddenly twist and displace sideways because its compression flange behaves like a column with little lateral support and the section has low torsional stiffness. Capacity falls with unbraced length. Prevent it with lateral bracing of the compression flange at close spacing, composite action with a slab, or choosing sections with high torsional and weak-axis stiffness, such as boxes.", c: ["Compression flange buckles sideways with twisting", "Capacity decreases with unbraced length", "Bracing the compression flange prevents it", "Composite slab or stiffer sections help"], k: ["Moment gradient raises the capacity", "Brace stiffness and strength must be adequate"], m: ["Checking only section strength in bending"] },
  { t: "Bridge bearings and expansion joints", p: "Why do bridges need bearings and expansion joints, and what movements must they accommodate?", d: 2, tp: "structural-design", tp2: "civil-materials", i: "Bridge decks change length with temperature, shrink and creep (for concrete), and rotate under traffic loads. Bearings transfer vertical and horizontal loads from deck to piers while allowing designed rotation and translation, and expansion joints bridge the deck gap so vehicles pass smoothly while permitting movement. Joints leak and wear, so many modern bridges use integral abutments to remove joints.", c: ["Thermal, shrinkage, creep and rotation movements", "Bearings transfer loads while allowing movement", "Expansion joints allow deck movement", "Integral abutments reduce maintenance"], k: ["Fixed and free bearing arrangement controls where movement happens", "Leaking joints damage substructures"], m: ["Restraining a bridge so thermal movement cannot occur"] },
  { t: "Design of a simple steel tension and compression truss member", p: "Which checks size a steel tension member versus a compression member?", d: 2, tp: "structural-design", i: "Tension members are checked for yielding of the gross section, fracture of the net section through bolt holes and block shear at connections, plus slenderness limits for vibration. Compression members are checked for flexural buckling about each axis, using the effective length and radius of gyration, with local buckling of plate elements limiting width-to-thickness ratios. Compression capacity is typically less than tension capacity for the same area.", c: ["Tension: gross yield, net fracture and block shear", "Compression: buckling about each axis", "Local buckling limits plate slenderness", "Compression capacity is lower for the same area"], k: ["Residual stress affects column curves", "Connections often govern"], m: ["Using the gross area for tension fracture checks"] },
  { t: "Foundation settlement tolerance of different structures", p: "Why can a flexible steel frame tolerate more settlement than a brick building?", d: 2, tp: "geotechnical", tp2: "structural-analysis", i: "Distress depends on angular distortion between supports, not on uniform settlement. Steel frames with flexible connections accommodate differential movement, while masonry is brittle and cracks at small angular distortion, about 1/300 for first cracking in walls. Tolerable settlement limits therefore differ by structure type, and uniform settlement matters mainly for services and access.", c: ["Angular distortion drives damage", "Steel frames tolerate it more", "Brick and masonry crack at small distortion", "Uniform settlement mainly affects services"], k: ["Typical limits are around 1/500 for sensitive frames", "Stiff foundations reduce differential movement"], m: ["Judging only by total settlement"] },
  { t: "Groundwater flow and Darcy's law in design", p: "State Darcy's law and explain how seepage affects dam and excavation design.", d: 2, tp: "hydraulics-hydrology", tp2: "groundwater-hydrology", i: "Darcy's law gives discharge velocity v = k·i, hydraulic conductivity times hydraulic gradient. Flow nets or numerical models determine seepage quantity and pore pressures under dams and around excavations. High exit gradients cause piping and erosion, and uplift pressures reduce stability, so designs use cut-offs, filters, drains and blankets to lower gradients and control seepage safely.", c: ["Darcy's law v = k i", "Flow nets or models give seepage and pore pressure", "High exit gradients cause piping", "Cut-offs, filters and drains control seepage"], k: ["Hydraulic conductivity varies enormously between soils", "Filter criteria prevent fines migration"], m: ["Ignoring uplift pressure under structures"] },
  { t: "Environmental flow and fish passage in culverts", p: "What design features make a road culvert passable for fish, and why do standard hydraulic designs often fail them?", d: 2, tp: "hydraulics-hydrology", tp2: "environmental-regulation", i: "Fish need water depth, moderate velocity and resting zones through the barrel. Standard culverts designed only for flood capacity often produce shallow, fast, smooth flow, perched outlets and high velocities that block migration. Fish-friendly designs use larger or open-bottom structures, embedded barrels with natural substrate, baffles for roughness and outlets matching the stream bed, often following stream-simulation design.", c: ["Fish need depth, low velocity and resting areas", "Flood-only culverts produce fast shallow flow and perched outlets", "Open-bottom or embedded designs with natural substrate", "Baffles and matched outlet elevation"], k: ["Regulatory permits often require passage", "Natural channel width is a design guide"], m: ["Sizing culverts only for flood flow"] },
  { t: "Structural health monitoring of bridges", p: "What do engineers monitor on an ageing bridge and how are readings used?", d: 2, tp: "structural-analysis", tp2: "fatigue-failure", i: "Typical measurements are strain, displacement, tilt, temperature, vibration frequencies and crack growth, using gauges, accelerometers and fibre-optic sensors, plus visual and non-destructive inspection. Changes in natural frequencies or strain patterns can signal stiffness loss or damage, and long-term data validate models and guide maintenance, load rating and replacement timing. Data need temperature compensation and thresholds to avoid false alarms.", c: ["Strain, displacement, tilt and vibration measurements", "Frequency or strain changes signal damage", "Data validate models and guide maintenance", "Temperature compensation is needed"], k: ["Baselines are needed for comparison", "Monitoring supplements, not replaces, inspection"], m: ["Reading raw data without temperature correction"] },
  { t: "Retrofit of buildings for earthquake resistance", p: "What are common seismic retrofit strategies for an older non-ductile concrete building?", d: 3, tp: "structural-design", tp2: "structural-analysis", i: "Strategies add strength or stiffness through shear walls or braced frames, improve ductility with column jacketing (fibre-wrap or steel) to confine concrete, strengthen connections and diaphragm-to-wall ties, or reduce demand with base isolation or dampers. Selection weighs performance objective, disruption, cost and heritage. Evaluation starts by finding the weak links, such as soft storeys and short columns.", c: ["Add shear walls or braced frames", "Jacket columns to add confinement", "Strengthen connections and diaphragm ties", "Isolation or damping reduces demand"], k: ["Weak-story and short-column failures are priorities", "Performance objectives guide the scope"], m: ["Stiffening one part without considering force redistribution"] },
  { t: "Mass transit capacity and headway", p: "How does headway relate to line capacity for rail transit, and what limits it?", d: 2, tp: "transportation", i: "Capacity in trains per hour is the inverse of headway, and passengers per hour is trains per hour times train capacity. Minimum headway is limited by signalling block length or moving-block spacing, braking distance, dwell time at stations (often the dominating factor) and terminal turnaround. Longer trains, shorter dwell times through level boarding and better signalling raise capacity.", c: ["Trains per hour is inverse headway", "Passengers per hour from train capacity", "Signalling, braking distance, dwell time and turnarounds limit headway", "Longer trains and better signalling raise capacity"], k: ["Station dwell is often the bottleneck", "Reliability affects effective capacity"], m: ["Thinking train speed alone sets capacity"] },
  { t: "Geosynthetics in soil reinforcement", p: "How do geogrids reinforce soil in a retaining wall or road base?", d: 2, tp: "geotechnical", tp2: "civil-materials", i: "Soil is strong in compression and shear but has almost no tensile strength. Geogrids placed in layers carry tension through interlock with the soil, restraining lateral movement, so the reinforced mass acts as a coherent gravity wall or a stiffer road base that distributes traffic loads and reduces rutting. Design checks internal pullout and rupture, external sliding and overturning and global stability.", c: ["Soil has no tensile strength", "Geogrids carry tension through interlock", "Reinforced mass acts like a gravity wall or stiff base", "Check pullout, rupture, sliding and global stability"], k: ["Spacing and length of layers control performance", "Creep of polymer reinforcement affects long-term design"], m: ["Placing reinforcement without checking pullout resistance"] },
  { t: "Life-cycle cost analysis for infrastructure choices", p: "How would you compare two bridge designs using life-cycle cost?", d: 2, tp: "construction-management", tp2: "structural-design", i: "Estimate initial construction cost plus future maintenance, rehabilitation, user delay costs and end-of-life costs over an analysis period, convert each to present value using a discount rate, and compare totals. Include uncertainty by testing different rates and service lives. A design with a higher initial cost can win through lower maintenance and user disruption, which simple first-cost comparison misses.", c: ["Include construction, maintenance, rehabilitation and user costs", "Discount future costs to present value", "Compare totals over the same analysis period", "Test sensitivity to discount rate and life"], k: ["User delay costs can dominate in busy corridors", "Different service lives need equivalent period or annualisation"], m: ["Selecting solely on initial cost"] },
];
